    Material3D water=LandscapeMaterial(Material3D{{1,1,1,.68f},{.12f,.08f,.04f,1},false},{.2f,.62f,.78f,.68f},.25f);water.materialClass=MaterialClass3D::Water;const Material3D foliageA=LandscapeMaterial(groundMaterial_,{.52f,.78f,.46f,1},.09f),foliageB=LandscapeMaterial(groundMaterial_,{.68f,.9f,.52f,1},.075f),trunk=LandscapeMaterial(woodMaterial_,{.78f,.64f,.46f,1},.52f),stone=LandscapeMaterial(brickMaterial_,{.72f,.76f,.74f,1},.28f),roof=LandscapeMaterial(brickMaterial_,{.48f,.2f,.14f,1},.3f);Material3D treeMaterial{{1,1,1,1},{.82f,0,.015f,.9f},true};
    const Material3D sky{{1,1,1,1},{1,0,0,1},false};landscapeScene_.Mesh(skyDomeMesh_,{{0,0,25},{},{360,260,360}},sky);landscapeScene_.Mesh(riverMesh_,{},water);for(int segment=0;segment<38;segment+=2){const float z=-25.f+float(segment)*3.f,centerX=25.f+std::sin(z*.105f)*5.f;for(float side:{-1.f,1.f}){const float rockX=centerX+side*3.7f;landscapeScene_.MeshLod(sphereHighMesh_,sphereLowMesh_,42,{{rockX,terrain_.SampleHeight(rockX,z)+.32f,z},{},{.72f,.48f,.72f}},stone);}}
