    Material3D cottageMaterial{{.82f,.78f,.7f,1},{.84f,.02f,.01f,.92f},true};constexpr std::array<Vec3,7> homes={Vec3{3,0,25},Vec3{11,0,25},Vec3{4,0,35},Vec3{13,0,36},Vec3{-2,0,45},Vec3{8,0,47},Vec3{17,0,46}};for(std::size_t index=0;index<homes.size();++index)AddHouse(landscapeScene_,terrain_,cottageHighMesh_,cottageLowMesh_,homes[index],.88f+float(index%3)*.055f,index%2?1.5708f:0.f,cottageMaterial);
    const Material3D mountain{{.72f,.76f,.74f,1},{.97f,0,0,.9f},false};for(int index=0;index<44;++index){const float side=index%2?-1.f:1.f,x=side*(48.f+float(index%4)*3.f),z=-18.f+float(index)*2.45f,height=10.f+LandscapeNoise(index,41)*15.f,y=terrain_.SampleHeight(x,z);landscapeScene_.MeshLod(mountainHighMesh_,mountainLowMesh_,75,{{x,y,z},{0,float(index)*.21f,0},{20.f+height*.3f,height,20.f+height*.3f}},mountain);}
    const float towerGround=terrain_.SampleHeight(0,18);landscapeScene_.Mesh(boxMesh_,{{0,towerGround+.5f,18},{},{7,1,7}},stone);landscapeScene_.Mesh(boxMesh_,{{0,towerGround+4.8f,18},{},{4.6f,8.6f,4.6f}},brickMaterial_);for(float x:{-2.15f,2.15f})for(float z:{15.85f,20.15f})landscapeScene_.Mesh(boxMesh_,{{x,towerGround+5.4f,z},{},{.65f,10,.65f}},trunk);landscapeScene_.Mesh(pyramidMesh_,{{0,towerGround+10.1f,18},{},{4.1f,3.2f,4.1f}},roof);landscapeScene_.MeshLod(sphereHighMesh_,sphereLowMesh_,45,{{0,towerGround+12.2f,18},{},{1.15f,1.15f,1.15f}},LandscapeMaterial(woodMaterial_,{1.f,.68f,.2f,1},.18f));
